    v5 = {}; run(SETUP_CODE, v5); v5["na_reason"] = "unsupported"; run(CLOSE_CODE, v5); print("CLOSE5:", v5["closing_line"])
    for r_ in ["unsupported", "done"]:
        compile(reason_code(r_), "rc", "exec")
    print("selftest ok")


if __name__ == "__main__":
    if sys.argv[1:] == ["--selftest"]:
