"""Generator for the statement-debt phone agent (Freya Bank, credit card statement debt, Turkish calls).

    python out/gen_BRIEF.py <tool base url ending in /voice/v1>     writes out/BRIEF.workflow.json
    python out/gen_BRIEF.py --selftest                              execs every hook on sample inputs

Every rule, wording and value comes from the case folder (BRIEF.md and its sources): the 8 Oct analysis,
the 9 Oct decisions mail (latest), the 7 Oct session, the 1 Oct service contract. Later records govern earlier ones.
All bank calls are engine-run (pre_actions); the model never calls a tool.
"""
import json, pathlib, sys

OUT = pathlib.Path(__file__).resolve().parent / "BRIEF.workflow.json"

# ---------------------------------------------------------------- fixed lines (verbatim from the sources)
L_MENU = "Sizi ana menüye yönlendiriyorum."
L_NO_CARD = "Ekstre borcunu sorgulayabileceğiniz uygun bir kredi kartınız bulunmuyor. Sizi ana menüye aktarıyorum."
L_TRIES = "Size şu anda yardımcı olamıyorum. Sizi ana menüye aktarıyorum."
L_MENU_AKT = "Sizi ana menüye aktarıyorum."
L_SILENCE = "Sesinizi alamadığım için görüşmeyi sonlandırıyorum."
L_AGENT = "Sizi müşteri temsilcimize aktarıyorum."
L_PAY = "Borç ödeme işleminiz için sizi müşteri temsilcimize aktarıyorum."
L_DISPUTE = "Bu konuda size müşteri temsilcimiz yardımcı olacak, sizi aktarıyorum."
L_ERROR = "Şu anda işleminizi gerçekleştiremiyorum, sizi müşteri temsilcimize aktarıyorum."
L_WEEK_ERROR = "Şu anda hesap kesim tarihinizi değiştiremiyorum, sizi müşteri temsilcimize aktarıyorum."
L_OOS_Q = "Size bu konuda yardımcı olamıyorum. Sizi ana menüye aktarmamı ister misiniz?"
L_SECURITY = ("Güvenlik nedeniyle yalnızca kendi kartlarınızla ilgili bilgi verebilir ve işlem yapabilirim. "
              "Kart sahibinin kendi kimliğiyle giriş yapabilmesi için sizi ana menüye aktarıyorum.")
L_NO_EMAIL = "Bankamızda kayıtlı bir e-posta adresiniz bulunmadığı için ekstrenizi gönderemiyorum."
L_SENT = "Ekstreniz kayıtlı e-posta adresinize gönderildi."
L_NOT_MINE = "Kayıtlı e-posta adresinizi bu görüşmede değiştiremiyorum. " + L_MENU
L_PAPER = "Ekstrenizi posta ya da kısa mesajla gönderemiyorum; yalnızca son ekstrenizi kayıtlı e-posta adresinize gönderebiliyorum. " + L_MENU
L_OTHER_CARD_Q = "Başka bir kartınızın borcunu öğrenmek ister misiniz?"

# ---------------------------------------------------------------- shared code (no double braces anywhere)
COMMON = r'''
import re, json, datetime
ONES = ['', 'bir', 'iki', 'üç', 'dört', 'beş', 'altı', 'yedi', 'sekiz', 'dokuz']
TENS = ['', 'on', 'yirmi', 'otuz', 'kırk', 'elli', 'altmış', 'yetmiş', 'seksen', 'doksan']
DIG = ['sıfır', 'bir', 'iki', 'üç', 'dört', 'beş', 'altı', 'yedi', 'sekiz', 'dokuz']
MONTHS = ['Ocak', 'Şubat', 'Mart', 'Nisan', 'Mayıs', 'Haziran', 'Temmuz', 'Ağustos', 'Eylül', 'Ekim', 'Kasım', 'Aralık']
CUR = [('TL', 'debtTL', 'Türk Lirası'), ('USD', 'debtUSD', 'Dolar'), ('EUR', 'debtEUR', 'Euro'), ('GBP', 'debtGBP', 'İngiliz Sterlini')]
def w3(n):
    p = []
    h, r = n // 100, n % 100
    if h:
        p.append('yüz' if h == 1 else ONES[h] + ' yüz')
    if r // 10:
        p.append(TENS[r // 10])
    if r % 10:
        p.append(ONES[r % 10])
    return ' '.join(p)
def words(n):
    n = int(n)
    if n == 0:
        return 'sıfır'
    out = []
    for val, name in ((10 ** 9, 'milyar'), (10 ** 6, 'milyon'), (1000, 'bin')):
        g = n // val
        n = n % val
        if g:
            if val == 1000 and g == 1:
                out.append('bin')
            else:
                out.append(w3(g) + ' ' + name)
    if n:
        out.append(w3(n))
    return ' '.join(out)
def num(x):
    try:
        return float(x)
    except Exception:
        return 0.0
def amount(x, cur):
    v = abs(num(x))
    cents = int(round(v * 100))
    whole, frac = cents // 100, cents % 100
    if cur == 'TL':
        if frac == 0:
            return words(whole) + ' Türk Lirası'
        return (words(whole) + ' lira ' if whole else '') + words(frac) + ' kuruş'
    if cur == 'USD':
        if frac == 0:
            return words(whole) + ' Dolar'
        return (words(whole) + ' dolar ' if whole else '') + words(frac) + ' sent'
    if cur == 'EUR':
        if frac == 0:
            return words(whole) + ' Euro'
        return (words(whole) + ' euro ' if whole else '') + words(frac) + ' sent'
    if frac == 0:
        return words(whole) + ' İngiliz Sterlini'
    return (words(whole) + ' sterlin ' if whole else '') + words(frac) + ' peni'
def suffix(phrase, apos=True):
    w = phrase.strip().split(' ')[-1]
    low = w.replace('I', 'ı').replace('İ', 'i').lower()
    vow = [ch for ch in low if ch in 'aeıioöuü']
    lv = vow[-1] if vow else 'e'
    v = dict(a='ı', ı='ı', e='i', i='i', o='u', u='u', ö='ü', ü='ü')[lv]
    cons = 't' if low[-1] in 'çfhkpsşt' else 'd'
    return phrase + ("'" if apos else '') + cons + v + 'r'
def amt_dir(x, cur):
    p = amount(x, cur)
    last = p.split(' ')[-1]
    return suffix(p, last[0].isupper())
def pdate(s):
    try:
        d, m, y = str(s).strip().split('.')
        return datetime.date(int(y), int(m), int(d))
    except Exception:
        return None
def sdate(d):
    return str(d.day) + ' ' + MONTHS[d.month - 1] + ' ' + str(d.year)
def sdate_dir(d):
    return sdate(d) + "'" + suffix(words(d.year), False)[len(words(d.year)):]
def today():
    try:
        return datetime.date.fromisoformat(str(vars.get('now') or '')[:10])
    except Exception:
        return datetime.date.today()
def digits_words(s):
    return ' '.join(DIG[int(ch)] for ch in str(s) if ch.isdigit())
def tlow(s):
    return str(s or '').replace('I', 'ı').replace('İ', 'i').lower()
def body_of(result):
    if isinstance(result, dict):
        result.pop('header', None)
        d = result.get('data')
        if isinstance(d, dict):
            return d
    return None
def ok_of(b):
    if not isinstance(b, dict):
        return False
    r = b.get('result')
    return isinstance(r, dict) and str(r.get('returnCode')) == '1' and isinstance(b.get('data'), dict)
def jl(name, dflt):
    try:
        v = json.loads(str(vars.get(name) or ''))
        return v
    except Exception:
        return dflt
def card_label(c):
    n = str(c.get('productName') or '').strip()
    if n:
        return n
    return 'sonu ' + digits_words(c.get('cardNumberLast4')) + ' ile biten kartınız'
def join_tr(items, conj='veya'):
    items = [i for i in items if i]
    if len(items) <= 1:
        return ''.join(items)
    return ', '.join(items[:-1]) + ' ' + conj + ' ' + items[-1]
def base_question(cards, exclude):
    names = []
    for i, c in enumerate(cards):
        if i in exclude or not c.get('main'):
            continue
        n = str(c.get('productName') or '').strip()
        if n and n not in names:
            names.append(n)
    q = 'Hangi kartınızın borcunu öğrenmek istersiniz?'
    if len(names) >= 2:
        q += ' Örneğin, ' + names[0] + ' veya ' + names[1] + ' diyebilirsiniz.'
    elif len(names) == 1:
        q += ' Örneğin, ' + names[0] + ' diyebilirsiniz.'
    return q
def all_names(cards):
    names = []
    for c in cards:
        if not c.get('main'):
            continue
        n = card_label(c)
        if n not in names:
            names.append(n)
    return names
'''

SETUP_CODE = r'''
try:
    vars['cards_state'] = 'error'
    vars['email_state'] = 'error'
    vars['sel_kind'] = 'none'
    vars['sel_tries'] = 0
    vars['sel_stage'] = 'name'
    vars['read_idx'] = '[]'
    vars['cand_json'] = '[]'
    vars['choice'] = 'none'
    vars['email_ok'] = 'none'
    vars['email_req'] = 'none'
    vars['wk_want'] = 'none'
    vars['wk_pick'] = 'none'
    vars['wk_confirm'] = 'none'
    vars['wk_tries'] = 0
    vars['conf_tries'] = 0
    vars['silence_n'] = 0
    vars['angry_n'] = 0
    vars['oos_ans'] = 'none'
    vars['sends'] = 0
    vars['bal_state'] = 'none'
    vars['reading_text'] = ''
    vars['offer_text'] = ''
    vars['after_q'] = ''
    vars['select_q'] = ''
    vars['email_q'] = ''
    vars['calm_line'] = ''
    vars['angry_state'] = 'calm'
    vars['silence_state'] = 'repeat'
except Exception:
    pass
'''

LIST_PRE = COMMON + r'''
try:
    vars['cards_state'] = 'error'
    config['body'] = dict(data=dict(customerNo=str(vars.get('customerNumber') or ''), aiFlow='CardOps'), call=dict(ani='', lang='tr'))
except Exception:
    pass
'''

LIST_POST = COMMON + r'''
try:
    b = body_of(result)
    if ok_of(b):
        raw = [c for c in (b['data'].get('cards') or []) if isinstance(c, dict)]
        cards = []
        for c in raw:
            cards.append(dict(cardNumber=str(c.get('cardNumber') or ''), cardNumberLast4=str(c.get('cardNumberLast4') or ''),
                              productName=str(c.get('productName') or ''), main=str(c.get('isMainCard')).lower() != 'false'))
        vars['cards_json'] = json.dumps(cards)
        mains = [i for i, c in enumerate(cards) if c['main']]
        vars['n_main'] = len(mains)
        if not mains:
            vars['cards_state'] = 'none'
        elif len(mains) == 1:
            vars['cards_state'] = 'one'
            c = cards[mains[0]]
            vars['sel_idx'] = mains[0]
            vars['sel_card'] = c['cardNumber']
        else:
            vars['cards_state'] = 'multi'
            vars['select_q'] = base_question(cards, [])
    elif isinstance(b, dict) and isinstance(b.get('result'), dict) and str(b['result'].get('code')) == 'FB_IVR_CHANNEL_102':
        vars['cards_state'] = 'none'
    if isinstance(result, dict) and isinstance(result.get('data'), dict):
        result['data'] = dict(note='Card list loaded. Do not read card numbers aloud.')
except Exception:
    pass
'''

EMAIL_PRE = COMMON + r'''
try:
    vars['email_state'] = 'error'
    config['body'] = dict(data=dict(customerNo=str(vars.get('customerNumber') or ''), intAddressInfoType='E'), call=dict(ani='', lang='tr'))
except Exception:
    pass
'''

EMAIL_POST = COMMON + r'''
try:
    b = body_of(result)
    if ok_of(b):
        d = b['data']
        em = str(d.get('ibanEmail') or '').strip()
        if em and '@' in em and str(d.get('communicationType') or '') != 'Phone':
            vars['email_state'] = 'has'
            vars['email_addr'] = em
            local, dom = em.split('@', 1)
            simple = re.fullmatch(r'[a-zA-Z]+(\.[a-zA-Z]+)?', local) is not None and len(local) <= 16
            if simple:
                vars['email_spoken'] = em
            else:
                vars['email_spoken'] = local[0].lower() + ' ile başlayan ' + dom.split('.')[0].capitalize() + ' adresiniz'
        else:
            vars['email_state'] = 'none'
        result['data'] = dict(note='Contact data loaded.')
except Exception:
    pass
'''

CARD_PRE = r'''
try:
    config['body'] = dict(data=dict(cardNumber=str(vars.get('sel_card') or '')), call=dict(ani='', lang='tr'))
    vars['bal_state'] = 'error'
except Exception:
    pass
'''

BAL_POST = COMMON + r'''
try:
    b = body_of(result)
    if ok_of(b):
        d = b['data']
        t = today()
        cards = jl('cards_json', [])
        si = int(vars.get('sel_idx') or 0)
        c = cards[si] if 0 <= si < len(cards) else dict()
        l4 = str(d.get('cardNumberLast4') or c.get('cardNumberLast4') or '')
        name = str(d.get('productName') or '').strip()
        l4w = digits_words(l4)
        intro = 'Sonu ' + l4w + ' ile biten ' + (name + ' kartınıza ait' if name else 'kartınıza ait')
        intro_gen = 'Sonu ' + l4w + ' ile biten ' + (name + ' kartınızın' if name else 'kartınızın')
        vars['sel_l4'] = l4
        vars['sel_name'] = name
        vars['sel_intro_gen'] = intro_gen
        st = pdate(d.get('statementDate'))
        due = pdate(d.get('lastPayDate'))
        blocks = []
        for code, key, label in CUR:
            blk = d.get(key)
            if isinstance(blk, dict) and blk:
                blocks.append((code, label, blk))
        def has(blk):
            return num(blk.get('remainingDebt')) > 0
        totals = [amount(blk.get('totalDebt'), code) for code, label, blk in blocks if num(blk.get('totalDebt')) > 0]
        parts = []
        if st is None:
            parts.append(intro + ' henüz kesilmiş bir ekstre bulunmadığı için ekstre borcunuz bulunmamaktadır.')
        elif t == st:
            parts.append(intro + ' hesap kesim tarihiniz bugün, ekstreniz saat 00.00 itibarıyla kesilecek.')
            if totals:
                parts.append('Gelecek dönemler dahil toplam borcunuz ' + join_tr(totals, 've') + "'dir." if False else 'Gelecek dönemler dahil toplam borcunuz ' + join_tr(totals, 've') + '.')
            else:
                parts.append('Borcunuz bulunmamaktadır.')
        elif str(d.get('statementPaymentStatus')) == 'NO_DEBT' or not any(has(blk) for code, label, blk in blocks):
            s = intro_gen + ' ' + sdate(st) + ' tarihli ekstresinden borcunuz bulunmamaktadır.'
            tl = [blk for code, label, blk in blocks if code == 'TL']
            if tl and num(tl[0].get('totalDebt')) > 0:
                s += ' Gelecek dönemler dahil toplam borcunuz ' + amt_dir(tl[0].get('totalDebt'), 'TL') + '.'
            if due is not None:
                s += ' Son ödeme tarihiniz ' + sdate(due) + ' olacaktır.'
            parts.append(s)
        elif due is not None and t > due:
            parts.append(intro + ' ' + sdate(st) + ' tarihinde kesilen ekstrenizin son ödeme tarihi olan ' + sdate(due) + ' geçmiştir.')
            if totals:
                parts.append('Toplam borcunuz ' + join_tr(totals, 've') + '.')
            if str(d.get('automaticPaymentFlag')) == 'Y':
                tlb = [blk for code, label, blk in blocks if code == 'TL']
                if tlb and num(tlb[0].get('remainAutomaticPaymentAmount')) > 0:
                    parts.append('Otomatik ödeme talimatınızdan tahsil edilecek kalan tutar ' + amt_dir(tlb[0].get('remainAutomaticPaymentAmount'), 'TL') + '.')
        else:
            lead = intro + ' ' + sdate(st) + ' tarihinde kesilen ekstre '
            moved = [label for code, label, blk in blocks if code != 'TL' and num(blk.get('transferAmount')) > 0]
            first = True
            if moved:
                parts.append(lead.strip() + 'de ' + join_tr(moved, 've') + ' borcunuzun bir kısmı Türk Lirası borcunuza aktarılmıştır.')
                first = False
            for code, label, blk in blocks:
                if not has(blk):
                    continue
                if code == 'TL':
                    sd, mp, rd, rmp = blk.get('statementDebt'), blk.get('minPayment'), blk.get('remainingDebt'), blk.get('remainingMinPayment')
                    if num(rmp) <= 0:
                        s = 'Türk Lirası borcunuz ' + amount(sd, 'TL') + ', kalan toplam borcunuz ' + amt_dir(rd, 'TL') + '. Minimum ödemenizi yaptığınız için teşekkür ederiz.'
                    elif num(rmp) >= num(mp):
                        s = 'Türk Lirası borcunuz ' + amount(sd, 'TL') + ', ödenmesi gereken minimum tutar ' + amt_dir(mp, 'TL') + '.'
                    else:
                        s = ('Türk Lirası borcunuz ' + amount(sd, 'TL') + ', ödenmesi gereken minimum tutar ' + amount(mp, 'TL')
                             + ', kalan toplam borcunuz ' + amount(rd, 'TL') + ', kalan minimum ödeme tutarınız ' + amt_dir(rmp, 'TL') + '.')
                else:
                    s = (label + ' borcunuz ' + amount(blk.get('statementDebt'), code) + ', kalan toplam borcunuz ' + amount(blk.get('remainingDebt'), code)
                         + ', ödenmesi gereken minimum tutar ' + amt_dir(blk.get('minPayment'), code) + '.')
                if first:
                    s = lead + s
                    first = False
                parts.append(s)
            clear = [label for code, label, blk in blocks if not has(blk)]
            if clear:
                parts.append(join_tr(clear, 've') + ' borcunuz bulunmamaktadır.')
            if due is not None:
                if due == t:
                    parts.append('Borçlarınız için son ödeme tarihiniz bugündür.')
                else:
                    parts.append('Borçlarınız için son ödeme tarihiniz ' + sdate_dir(due) + '.')
        vars['reading_text'] = ' '.join(parts)
        read = jl('read_idx', [])
        if si not in read:
            read.append(si)
        vars['read_idx'] = json.dumps(read)
        left = [i for i, cc in enumerate(cards) if cc.get('main') and i not in read]
        vars['cards_left'] = len(left)
        vars['bal_state'] = 'ok'
        result['data'] = dict(note='The reading text is spoken by the system. Do not read figures yourself.')
except Exception:
    pass
'''

MATCH_CODE = COMMON + r'''
try:
    cards = jl('cards_json', [])
    kind = str(vars.get('sel_kind') or 'none')
    name = tlow(vars.get('sel_name_said') or '').strip()
    dg = re.sub(r'\D', '', str(vars.get('sel_digits') or ''))
    stage = str(vars.get('sel_stage') or 'name')
    cand = jl('cand_json', [])
    pool = cand if cand else list(range(len(cards)))
    exclude = jl('read_idx', []) if False else []
    tries = int(vars.get('sel_tries') or 0)
    res, q, chosen, newstage, newcand, failed = '', '', None, stage, cand, False
    def stage_q(st, cnd, dgt):
        if st == 'last4':
            nm = str(cards[cnd[0]].get('productName') or '') if cnd else ''
            return (nm + ' isimli birden fazla kartınız var. ' if nm else '') + 'Kartınızın son dört hanesini söyler misiniz?'
        if st == 'last6':
            return 'Son dört hanesi ' + digits_words(dgt[-4:]) + ' olan birden fazla kartınız var. Kartınızın son altı hanesini söyler misiniz?'
        if st == 'full':
            return 'Son altı hanesi aynı olan birden fazla kartınız var. Kart numaranızı söyler misiniz?'
        return base_question(cards, [])
    def fits_mask(mask, d):
        m = re.sub(r'[^0-9*]', '', mask)
        if len(d) > len(m):
            return False
        tail = m[len(m) - len(d):]
        return all(a == '*' or a == b for a, b in zip(tail, d))
    if kind == 'all':
        failed = True
        q = 'Borç bilgisini kart kart verebiliyorum. ' + base_question(cards, [])
        newstage, newcand = 'name', []
    elif len(dg) >= 4:
        if len(dg) >= 12:
            hits = [i for i in range(len(cards)) if fits_mask(cards[i]['cardNumber'], dg) and len(re.sub(r'[^0-9*]', '', cards[i]['cardNumber'])) == len(dg)]
        elif len(dg) >= 6:
            hits = [i for i in pool if fits_mask(cards[i]['cardNumber'], dg[-6:])]
            if not hits:
                hits = [i for i in range(len(cards)) if fits_mask(cards[i]['cardNumber'], dg[-6:])]
        else:
            hits = [i for i in pool if cards[i]['cardNumberLast4'] == dg[-4:]]
            if not hits:
                hits = [i for i in range(len(cards)) if cards[i]['cardNumberLast4'] == dg[-4:]]
        if len(hits) == 1:
            chosen = hits[0]
        elif len(hits) > 1:
            newcand = hits
            if len(dg) >= 12:
                failed = True
                q = 'Kart numaranızı tekrar söyler misiniz?'
            elif len(dg) >= 6:
                newstage = 'full'
                q = stage_q('full', hits, dg)
            else:
                newstage = 'last6'
                vars['sel_last4'] = dg[-4:]
                q = stage_q('last6', hits, dg)
        else:
            failed = True
            q = 'Söylediğiniz numarayla eşleşen bir kartınız bulunmuyor. ' + stage_q(stage if stage != 'name' else 'last4', cand, str(vars.get('sel_last4') or ''))
            if stage == 'name':
                newstage = 'name'
                q = 'Söylediğiniz numarayla eşleşen bir kartınız bulunmuyor. Kartlarınız: ' + join_tr(all_names(cards), 've') + '. Hangisinin borcunu öğrenmek istersiniz?'
    elif name:
        stop = set(['kart', 'kartı', 'kartım', 'kartımın', 'kartımı', 'kartının', 'kredi', 'olan', 'benim', 've', 'ile'])
        toks = [w for w in re.split(r'[^0-9a-zçğıöşü]+', name) if w and w not in stop]
        exact = [i for i in range(len(cards)) if tlow(cards[i].get('productName')).strip() == ' '.join(toks)]
        def part(i):
            pt = [w for w in re.split(r'[^0-9a-zçğıöşü]+', tlow(cards[i].get('productName'))) if w]
            if not toks or not pt:
                return False
            return all(any(p == w or (len(w) >= 3 and (p.startswith(w) or w.startswith(p))) for p in pt) for w in toks)
        hits = exact or [i for i in range(len(cards)) if part(i)]
        if cand and len(set(hits) & set(cand)) >= 1:
            hits = [i for i in hits if i in cand]
        if len(hits) == 1:
