        run(MATCH_CODE, v); print("->", v["sel_result"], v.get("sel_card"))
        v = {"now": "2026-10-12T10:30:00+03:00", "customerNumber": "97526380"}
        run(SETUP_CODE, v)
        run(LIST_POST, v, None, env(cust["97526380"]["services"]["cards.list"]))
        print("Q:", v["select_q"])
        v.update(sel_kind="all"); run(MATCH_CODE, v); print("->", v["sel_result"], v["sel_tries"], v["select_q"])
        v.update(sel_kind="name", sel_name_said="premium kartım"); run(MATCH_CODE, v); print("->", v["sel_result"], v.get("sel_card"))
