        run(SETUP_CODE, v); run(LIST_POST, v, None, env(cust["93261864"]["services"]["cards.list"]))
        v.update(sel_kind="name", sel_name_said="Miles"); run(MATCH_CODE, v); print("Miles ->", v["sel_result"], v["select_q"])
        v.update(sel_kind="name", sel_name_said="Bonus"); run(MATCH_CODE, v); print("Bonus ->", v["sel_result"], v["select_q"])
        v = {"now": "2026-10-12T10:30:00+03:00", "customerNumber": "95813998"}
        run(SETUP_CODE, v); run(LIST_POST, v, None, env(cust["95813998"]["services"]["cards.list"]))
