        v["wk_pick"] = "3"; run(WEEK_VALIDATE_CODE, v); print("pick3:", v["wk_route"], v["week_options_text"])
        v["wk_pick"] = "2"; run(WEEK_VALIDATE_CODE, v); print("pick2:", v["wk_route"])
        cfg = {"body": {}}; run(DECIDE_PRE, v, cfg); print(cfg)
        run(DECIDE_POST, v, None, env(cust["92220795"]["services"]["statement.week.decide"][v["sel_card"]]["2"]))
        print(v["confirm_text"], "|", v["done_text"])
        run(CONF_RETRY_CODE, v); print(v["confirm_plain"])
        run(CHANGE_PRE, v, {"body": {}})
        run(CHANGE_POST, v, None, env(cust["92220795"]["services"]["statement.week.change"][v["sel_card"]]["2"])); assert v["change_state"] == "ok"
        v["email_req"] = "older"; run(EMAIL_PREP_CODE, v); print(v["email_route"], v["email_q"])
        cfg = {"body": {}}; run(PDF_PRE, v, cfg); print(cfg)
        run(PDF_POST, v, None, env(cust["92220795"]["services"]["statement.pdf.send"])); assert v["pdf_state"] == "ok"
        v["email_ok"] = "vague"; run(EMAIL_RETRY_CODE, v); print(v["email_q"])
        # due today, statement today, due passed
        v = {"now": "2026-10-15T10:30:00+03:00", "customerNumber": "95004361"}
        run(SETUP_CODE, v); run(LIST_POST, v, None, env(cust["95004361"]["services"]["cards.list"])); call_bal(v, v["sel_card"]); print("DUE TODAY:", v["reading_text"])
        v["now"] = "2026-10-05T10:00"; call_bal(v, v["sel_card"]); print("CUT TODAY:", v["reading_text"])
        v["now"] = "2026-10-20T10:00"; call_bal(v, v["sel_card"]); print("PASSED:", v["reading_text"])
    for i in range(5):
