        def part(i):
            pt = [w for w in re.split(r'[^0-9a-zçğıöşü]+', tlow(cards[i].get('productName'))) if w]
            if not toks or not pt:
                return False
            return all(any(p == w or (len(w) >= 3 and (p.startswith(w) or w.startswith(p))) for p in pt) for w in toks)
        hits = exact or [i for i in range(len(cards)) if part(i)]
