        failed = False
        newstage, newcand = 'name', []
        q = 'Bu kartınız için ekstre borcu sorgulanamıyor. Lütfen başka bir kartınızı seçin. ' + base_question(cards, [])
    if chosen is not None:
        vars['sel_idx'] = chosen
