    ex("sel_digits", "Card digits the caller said in the latest message, converted to digits only, in order. Spoken numbers count: 'kırk iki elli üç' = 4253, 'dört iki beş üç' = 4253, 'on bir sıfır bir' = 1101. Empty if none."),
]

SEL_TASK = """Arayanın hangi kartının borcunu öğrenmek istediğini netleştir. Son sorduğun soru: "{{select_q}}"
- Arayan tekrar duymak isterse veya sessiz kalırsa bu soruyu kısaca tekrar sor.
- Kart seçimini sen yapma ve hiçbir kartın borcunu, rakamını söyleme; arayanın cevabını sistem değerlendirir.
- Kart adı örneklerini yalnızca bu sorudaki adlardan ver; arayanın sahip olmadığı bir kart adını asla söyleme."""


def build(base):
    base = base.rstrip("/")
    N = {}
    N["setup"] = code_node("setup", SETUP_CODE, [], "cards_list")
    N["cards_list"] = api_node("cards_list", base, "cards.list", LIST_PRE, LIST_POST, [], "contact_email", timeout=15000, retries=1,
                               body={"data": {"type": "object", "default": {"customerNo": "{{customerNumber}}", "aiFlow": "CardOps"}},
                                     "call": {"type": "object", "default": {"ani": "", "lang": "tr"}}})
    N["contact_email"] = api_node("contact_email", base, "contact.email.get", EMAIL_PRE, EMAIL_POST, [
        tr("end_no_card", "No eligible card", eq("cards_state", "none")),
        tr("cards_balance", "One card", eq("cards_state", "one")),
        tr("select_card", "Several cards", eq("cards_state", "multi"))], "end_error", timeout=15000, retries=1,
        body={"data": {"type": "object", "default": {"customerNo": "{{customerNumber}}", "intAddressInfoType": "E"}},
              "call": {"type": "object", "default": {"ani": "", "lang": "tr"}}})
    # card selection
    N["select_card"] = conv("select_card", "{{select_q}}", SEL_TASK, SEL_EXTRACT, [
        tr("match_card", "The caller answered the card question", grp(c("sel_kind", "equals", "name"), c("sel_kind", "equals", "digits"),
                                                                       c("sel_kind", "equals", "all"), c("sel_kind", "equals", "unclear")))], turns=10)
    N["match_card"] = code_node("match_card", MATCH_CODE, [
        tr("cards_balance", "Card chosen", eq("sel_result", "ok")),
        tr("end_tries", "Three tries used", eq("sel_result", "giveup"))], "select_card")
    N["cards_balance"] = api_node("cards_balance", base, "cards.balance", CARD_PRE, BAL_POST, [
        tr("after_read", "Balance read", eq("bal_state", "ok"))], "end_error", timeout=30000, retries=0,
        body={"data": {"type": "object", "default": {"cardNumber": "{{sel_card}}"}},
              "call": {"type": "object", "default": {"ani": "", "lang": "tr"}}})
    N["after_read"] = code_node("after_read", AFTER_READ_CODE, [
        tr("say_reading_other", "Other cards left", eq("after_stage", "other")),
        tr("end_reading_error", "Contact service failed", eq("after_stage", "error"))], "say_reading_offer")
    N["say_reading_other"] = say_node("say_reading_other", "{{reading_text}}", "ask_other")
    N["say_reading_offer"] = say_node("say_reading_offer", "{{reading_text}}", "offer")
    OFFER_EXTRACT = [
        ex("choice", "What the caller wants now, from the LATEST message: other_card (the debt of another of their cards; also a yes to 'Başka bir kartınızın borcunu öğrenmek ister misiniz?'), no (a no to that other-card question), email (the statement sent by e-mail), week (change / move the statement date or week, 'hesap kesim tarihi'), done (nothing else, thanks, goodbye, 'yok', 'teşekkürler'). Leave empty for anything else (a repeat request, silence, a question).",
           ["other_card", "no", "email", "week", "done"]),
        ex("email_req", "Only when the caller asks for the statement by e-mail: older (asks for last month's or an earlier statement), other_address (wants it sent to another address than the registered one), paper (wants it by post/paper or SMS), normal (otherwise).",
           ["older", "other_address", "paper", "normal"]),
    ] + SEL_EXTRACT[1:]
    READ_REPEAT = "Okunan borç bilgisi (arayan tekrar isterse aynen tekrar et): \"{{reading_text}}\""
    N["ask_other"] = conv("ask_other", L_OTHER_CARD_Q,
                          READ_REPEAT + "\nSorduğun soru: \"" + L_OTHER_CARD_Q + "\" Arayanın cevabını bekle; gerekirse soruyu tekrar sor.",
                          OFFER_EXTRACT, [
                              tr("other_card_prep", "Wants another card", grp(c("choice", "equals", "other_card"))),
                              tr("to_offer", "No other card", grp(c("choice", "equals", "no"), c("choice", "equals", "done"))),
                              tr("email_prep", "Wants e-mail", eq("choice", "email")),
                              tr("week_get", "Wants week change", eq("choice", "week"))])
    N["other_card_prep"] = code_node("other_card_prep", OTHER_CARD_CODE, [], "select_card")
    N["to_offer"] = code_node("to_offer", TO_OFFER_CODE, [tr("end_error", "Contact service failed", eq("after_stage", "error"))], "offer")
    N["offer"] = conv("offer", "{{offer_text}}",
                      READ_REPEAT + "\nSunduğun seçenekler: \"{{offer_text}}\" Arayan başka bir şey istemiyorsa bunu sistem anlar. Belirsiz bir cevapta seçenekleri kısaca tekrar söyle.",
                      OFFER_EXTRACT, [
                          tr("end_menu", "Nothing else", grp(c("choice", "equals", "done"), c("choice", "equals", "no"))),
                          tr("email_prep", "Wants e-mail", eq("choice", "email")),
                          tr("week_get", "Wants week change", eq("choice", "week")),
                          tr("other_card_prep", "Wants another card", eq("choice", "other_card"))])
    # e-mail
    N["email_prep"] = code_node("email_prep", EMAIL_PREP_CODE, [
        tr("end_paper", "Paper / SMS", eq("email_route", "paper")),
        tr("offer", "No registered e-mail", eq("email_route", "none")),
        tr("end_error", "Contact failed", eq("email_route", "error"))], "email_confirm")
    N["email_confirm"] = conv("email_confirm", "{{email_q}}",
                              "Sorduğun soru: \"{{email_q}}\" Yalnızca son kesilen ekstre ve yalnızca bankada kayıtlı adres gönderilebilir; başka adres, eski dönem ekstresi, posta veya SMS mümkün değil. Adresi harf harf okuma. Gönderildi deme; gönderimi sistem yapar.",
                              [ex("email_ok", "The caller's answer to the send question in the LATEST message: yes (a clear yes: 'evet', 'gönderin', 'olur gönder'), no (does not want it), not_mine (says that address is not theirs / not used any more / wrong), other_address (wants another address), vague (hedged: 'olabilir', 'herhalde', 'bilmem'). Leave empty for silence or a repeat request.",
                                  ["yes", "no", "not_mine", "other_address", "vague"])], [
                                  tr("pdf_send", "Clear yes", eq("email_ok", "yes")),
                                  tr("end_menu", "No", eq("email_ok", "no")),
                                  tr("end_not_mine", "Not my address", eq("email_ok", "not_mine")),
                                  tr("email_retry", "Unclear", grp(c("email_ok", "equals", "vague"), c("email_ok", "equals", "other_address")))])
    N["email_retry"] = code_node("email_retry", EMAIL_RETRY_CODE, [tr("end_tries", "Three tries", eq("conf_route", "giveup"))], "email_confirm")
    N["pdf_send"] = api_node("pdf_send", base, "statement.pdf.send", PDF_PRE, PDF_POST, [
        tr("end_sent", "Sent", eq("pdf_state", "ok"))], "end_error", timeout=20000, retries=0,
        body={"data": {"type": "object", "default": {"customerNo": "{{customerNumber}}", "cardNumber": "{{sel_card}}", "currencyType": "TL",
                                                      "statementDate": "{{sel_statement_date}}", "emailAddress": "{{email_addr}}"}},
              "call": {"type": "object", "default": {"ani": "", "lang": "tr"}}})
    # statement week
    N["week_get"] = api_node("week_get", base, "statement.week.get", WEEK_GET_PRE, WEEK_GET_POST, [
        tr("week_ask", "Loaded", eq("week_state", "ok"))], "end_week_error", timeout=15000, retries=1,
        body={"data": {"type": "object", "default": {"cardNumber": "{{sel_card}}"}},
              "call": {"type": "object", "default": {"ani": "", "lang": "tr"}}})
    WK_PICK = ex("wk_pick", "The week of the month (1, 2, 3 or 4) the caller chooses in the LATEST message ('üçüncü hafta' = 3, 'ayın 3. haftası' = 3). other if they name a day of the month, a date or anything that is not a week number 1-4. Empty if they name no week.",
                 ["1", "2", "3", "4", "other"])
    N["week_ask"] = conv("week_ask", "{{week_info}}",
                         "Sorduğun soru: \"{{week_info}}\" Hesap kesim tarihi yılda bir kez değiştirilebilir. Değişikliği sen yapmazsın; tarih hesaplama.",
                         [ex("wk_want", "Does the caller want to change the statement week, in the LATEST message: yes or no. Empty if unclear.", ["yes", "no"]), WK_PICK], [
                             tr("week_validate", "Week named", grp(c("wk_pick", "equals", "1"), c("wk_pick", "equals", "2"), c("wk_pick", "equals", "3"),
                                                                   c("wk_pick", "equals", "4"), c("wk_pick", "equals", "other"))),
                             tr("week_options", "Wants change", eq("wk_want", "yes")),
                             tr("end_menu", "Does not want change", eq("wk_want", "no"))])
    N["week_options"] = conv("week_options", "{{week_options_text}}",
                             "Sorduğun soru: \"{{week_options_text}}\" Yalnızca bu haftalar seçilebilir. Tarih hesaplama; yeni tarihleri sistem söyler.",
                             [WK_PICK, ex("wk_want", "no if the caller now says they do not want any change after all. Empty otherwise.", ["no"])], [
                                 tr("week_validate", "Week named", grp(c("wk_pick", "equals", "1"), c("wk_pick", "equals", "2"), c("wk_pick", "equals", "3"),
                                                                       c("wk_pick", "equals", "4"), c("wk_pick", "equals", "other"))),
                                 tr("end_menu", "No change", eq("wk_want", "no"))])
    N["week_validate"] = code_node("week_validate", WEEK_VALIDATE_CODE, [
        tr("week_decide", "Valid week", eq("wk_route", "decide")),
        tr("end_tries", "Three tries", eq("wk_route", "giveup"))], "week_options")
    N["week_decide"] = api_node("week_decide", base, "statement.week.decide", DECIDE_PRE, DECIDE_POST, [
        tr("week_confirm", "Preview", eq("decide_state", "ok"))], "end_week_error", timeout=15000, retries=1,
        body={"data": {"type": "object", "default": {"cardNumber": "{{sel_card}}", "newStatementWeek": "{{new_week}}", "statementDay": "{{cur_day}}"}},
              "call": {"type": "object", "default": {"ani": "", "lang": "tr"}}})
    CONF_EX = [ex("wk_confirm", "The caller's answer to 'Onaylıyor musunuz?' in the LATEST message: yes ONLY for a clear yes ('evet', 'evet onaylıyorum', 'onaylıyorum'); no for a no or a cancel; vague for anything hedged or conditional ('olur herhalde', 'sanırım', 'olabilir', 'bilmem', 'tamam galiba') or a demand to just do it without saying yes. Empty for silence or a repeat request.",
                  ["yes", "no", "vague"], conf=0.5)]
    CONF_TASK = "Sorduğun soru: \"{{confirm_text}}\" Değişikliği sen yapmazsın ve yapıldı demezsin. Yalnızca açık bir \"evet\" onay sayılır. Tarihleri yalnızca bu metinden söyle."
    N["week_confirm"] = conv("week_confirm", "{{confirm_text}}", CONF_TASK, CONF_EX, [
        tr("week_change", "Clear yes", eq("wk_confirm", "yes")),
        tr("end_menu", "No", eq("wk_confirm", "no")),
        tr("conf_retry", "Vague", eq("wk_confirm", "vague"))])
    N["conf_retry"] = code_node("conf_retry", CONF_RETRY_CODE, [tr("end_tries", "Three tries", eq("conf_route", "giveup"))], "week_confirm2")
    N["week_confirm2"] = conv("week_confirm2", "{{confirm_plain}}", CONF_TASK.replace("confirm_text", "confirm_plain"), CONF_EX, [
        tr("week_change", "Clear yes", eq("wk_confirm", "yes")),
        tr("end_menu", "No", eq("wk_confirm", "no")),
        tr("conf_retry", "Vague", eq("wk_confirm", "vague"))])
    N["week_change"] = api_node("week_change", base, "statement.week.change", CHANGE_PRE, CHANGE_POST, [
        tr("end_changed", "Changed", eq("change_state", "ok"))], "end_week_error", timeout=20000, retries=0,
        body={"data": {"type": "object", "default": {"cardNumber": "{{sel_card}}", "newStatementWeek": "{{new_week}}", "statementDay": "{{cur_day}}"}},
              "call": {"type": "object", "default": {"ani": "", "lang": "tr"}}})
    # wrap nodes: say the result, then one more turn so a third-party request still gets the security answer
    N["end_changed"] = {"name": "end_changed", "node_type": "conversation", "on_enter": {"type": "tts", "text": "{{done_text}} " + L_MENU},
                        "task_message": "The change is done and the caller is being routed to the main menu. No tool call is allowed.",
                        "transitions": [tr("end_security", "Third party", {"operator": "matches_intent", "description": "The caller asks about or wants a transaction on another person's card (spouse, wife, husband, mother, father, relative, friend)"}),
                                        tr("end_silent", "Anything else", ALWAYS)]}
    N["end_sent"] = {"name": "end_sent", "node_type": "conversation", "on_enter": {"type": "tts", "text": L_SENT + " " + L_MENU},
                     "task_message": "The statement was sent and the caller is being routed to the main menu. No tool call is allowed.",
                     "transitions": [tr("end_security", "Third party", {"operator": "matches_intent", "description": "The caller asks about or wants a transaction on another person's card (spouse, wife, husband, mother, father, relative, friend)"}),
                                     tr("end_silent", "Anything else", ALWAYS)]}
    # ends
    N["end_silent"] = {"name": "end_silent", "node_type": "end_call", "on_enter": {"type": "silent"}, "disable_inactivity_monitor": True,
                       "transitions": [], "terminal": {"type": "function", "function": {"name": "main_menu", "handler": "__function__:end_call",
                                                                                         "parameters": {"type": "object", "properties": {"message_mode": {"type": "string", "default": "none"}}}}}}
    N["end_menu"] = end_node("end_menu", "main_menu", L_MENU)
    N["end_no_card"] = end_node("end_no_card", "main_menu_no_card", L_NO_CARD)
    N["end_tries"] = end_node("end_tries", "main_menu_tries", L_TRIES)
    N["end_oos"] = end_node("end_oos", "main_menu_out_of_scope", L_MENU_AKT)
    N["end_lang"] = end_node("end_lang", "main_menu_language", L_MENU_AKT)
    N["end_silence"] = end_node("end_silence", "call_closed_silence", L_SILENCE)
    N["end_agent"] = end_node("end_agent", "agent_transfer", L_AGENT)
    N["end_pay"] = end_node("end_pay", "agent_transfer_payment", L_PAY)
    N["end_dispute"] = end_node("end_dispute", "agent_transfer_dispute", L_DISPUTE)
    N["end_error"] = end_node("end_error", "agent_transfer_service_error", L_ERROR)
    N["end_reading_error"] = end_node("end_reading_error", "agent_transfer_service_error", "{{reading_text}} " + L_ERROR)
    N["end_week_error"] = end_node("end_week_error", "agent_transfer_week_error", L_WEEK_ERROR)
    N["end_security"] = end_node("end_security", "ivr_login_security", L_SECURITY)
    N["end_not_mine"] = end_node("end_not_mine", "main_menu", L_NOT_MINE)
    N["end_paper"] = end_node("end_paper", "main_menu", L_PAPER)

    excluded = [k for k in N if k.startswith("end_") or N[k]["node_type"] in ("code", "api_request")]
    excluded = sorted(set(excluded) | {"end_changed", "end_sent"})

    def g_end(name, intent, target, excl=None):
        return {"name": name, "node_type": "api_request", "description": intent,
                "condition": {"operator": "matches_intent", "description": intent},
                "passthrough": True, "passthrough_default_transition": target, "on_enter": {"type": "silent"},
                "disable_inactivity_monitor": True, "excluded_nodes": excl or excluded, "transitions": [tr(target, "always", ALWAYS)]}

    G = {}
    G["g_agent"] = g_end("g_agent", "The caller explicitly asks to speak to a person / customer representative / human agent ('müşteri temsilcisi', 'operatör', 'bir insanla görüşmek istiyorum').", "end_agent")
    G["g_pay"] = g_end("g_pay", "The caller wants to pay the card debt now, or asks how, where or through which channel to pay (app, branch, ATM, automatic payment). Asking only how much the debt is, is NOT this.", "end_pay")
    G["g_dispute"] = g_end("g_dispute", "The caller says the debt amount is wrong, objects to a charge on the statement, or says a payment they made is not showing.", "end_pay".replace("end_pay", "end_dispute"))
    G["g_third"] = g_end("g_third", "The caller asks about, or wants information or a transaction on, a card that belongs to ANOTHER person (spouse, wife, husband, mother, father, child, relative, friend). Their own cards are NOT this.", "end_security")
    G["g_lang"] = g_end("g_lang", "The caller's latest message is not in Turkish (for example English, German or Arabic sentences).", "end_lang")
    G["g_silence"] = {"name": "g_silence", "node_type": "code", "description": "Silence",
                      "condition": {"operator": "matches_intent", "description": "The caller's latest message is empty, only dots or ellipsis, or a silence / no-input marker (e.g. '...', '[sessizlik]', '(silence)')."},
                      "passthrough": True, "passthrough_default_transition": "__previous__", "on_enter": {"type": "silent"},
                      "disable_inactivity_monitor": True, "excluded_nodes": excluded,
                      "pre_actions": code_node("x", SILENCE_CODE, [], "x")["pre_actions"],
                      "transitions": [tr("end_silence", "Third silence", eq("silence_state", "end")), tr("__previous__", "always", ALWAYS)]}
    G["g_angry"] = {"name": "g_angry", "node_type": "code", "description": "Upset caller",
                    "condition": {"operator": "matches_intent", "description": "The caller is clearly angry or upset, complains loudly about the bank or the service, raises their voice or swears, without asking for a person, a payment or making a factual dispute about the amount."},
                    "passthrough": True, "passthrough_default_transition": "__previous__", "on_enter": {"type": "tts", "text": "{{calm_line}}"},
                    "disable_inactivity_monitor": True, "excluded_nodes": excluded,
                    "pre_actions": code_node("x", ANGRY_CODE, [], "x")["pre_actions"],
                    "transitions": [tr("end_agent", "Still complaining after three calming replies", eq("angry_state", "transfer")), tr("__previous__", "always", ALWAYS)]}
    G["g_oos"] = {"name": "g_oos", "node_type": "conversation", "description": "Out of scope question",
                  "condition": {"operator": "matches_intent", "description": "The caller asks about something outside the card statement debt, the statement e-mail and the statement date change: e.g. interest or late-payment rates, card limit or available limit, points or miles, instalments, loans, card blocking, address change, branch hours, or another banking transaction. Paying the debt, a disputed amount, a request for a person, or another person's card are NOT this."},
                  "on_enter": {"type": "tts", "text": L_OOS_Q}, "excluded_nodes": excluded + ["g_oos"],
                  "task_message": "Sorduğun soru: \"" + L_OOS_Q + "\" Konu hakkında bilgi verme. Belirsiz cevapta soruyu tekrar sor.\n\nNo tool call is allowed in this step. Reply in Turkish.",
                  "extraction_schema": [ex("oos_ans", "Answer to 'Sizi ana menüye aktarmamı ister misiniz?' in the LATEST message: yes (go to the main menu) or no (wants to continue here). Empty if unclear.", ["yes", "no"])],
                  "max_node_turns": 4, "max_turn_transition": "end_tries",
                  "transitions": [tr("end_oos", "Yes", eq("oos_ans", "yes")), tr("__previous__", "Continue", eq("oos_ans", "no"))]}
    return {"initial_node": "setup", "system_prompt": SYSTEM, "nodes": N, "global_nodes": G,
            "test_variables": {"customerNumber": "95004361", "now": "2026-10-12T10:30:00+03:00"}}


def selftest():
    for k, src in ALL_HOOKS.items():
        assert "{{" not in src and "}}" not in src, k
        compile(src, k, "exec")

    def run(src, v, config=None, result=None):
        g = {"vars": v, "config": config, "result": result}
        exec(src, g)
        return g
    data = json.load(open(sys.argv[2], encoding="utf-8")) if len(sys.argv) > 2 else None
    v = {"now": "2026-10-12T10:30:00+03:00", "customerNumber": "95004361"}
    run(SETUP_CODE, v)
    cfg = {"body": {}}
    run(LIST_PRE, v, cfg)
    assert cfg["body"]["data"]["customerNo"] == "95004361"
    if data:
        cust = {c_["customerNo"]: c_ for c_ in data["customers"]}

        def env(entry):
            return {"status": "success", "data": json.loads(json.dumps(entry["response"])), "status_code": entry["http"], "header": {}}

        def call_bal(v, card):
            run(CARD_PRE, v, {"body": {}})
            run(BAL_POST, v, None, env(cust[v["customerNumber"]]["services"]["cards.balance"][card]))
            return v
        for cn in ["95004361", "96158684", "92460108", "96125950", "92311921", "97631186", "92220795", "96451507", "94896459", "97974112", "92122831"]:
            v = {"now": "2026-10-12T10:30:00+03:00", "customerNumber": cn}
            run(SETUP_CODE, v)
            run(LIST_POST, v, None, env(cust[cn]["services"]["cards.list"]))
            run(EMAIL_POST, v, None, env(cust[cn]["services"]["contact.email.get"]))
            cards = json.loads(v["cards_json"])
            for i, cd in enumerate(cards):
                v["sel_idx"] = i
                v["sel_card"] = cd["cardNumber"]
                call_bal(v, cd["cardNumber"])
                print(cn, v["cards_state"], v["email_state"], v.get("email_spoken"), "|", v["reading_text"])
        # matching
        v = {"now": "2026-10-12T10:30:00+03:00", "customerNumber": "92030487"}
        run(SETUP_CODE, v)
        run(LIST_POST, v, None, env(cust["92030487"]["services"]["cards.list"]))
        print("Q:", v["select_q"])
        v.update(sel_kind="name", sel_name_said="Yıldız Pratik")
        run(MATCH_CODE, v); print("->", v["sel_result"], v["select_q"])
        v.update(sel_kind="digits", sel_digits="4253")
        run(MATCH_CODE, v); print("->", v["sel_result"], v["select_q"])
        v.update(sel_kind="digits", sel_digits="004253")
        run(MATCH_CODE, v); print("->", v["sel_result"], v["select_q"])
        v.update(sel_kind="digits", sel_digits="5450001234564253")
        run(MATCH_CODE, v); print("->", v["sel_result"], v.get("sel_card"))
        v = {"now": "2026-10-12T10:30:00+03:00", "customerNumber": "97526380"}
        run(SETUP_CODE, v)
        run(LIST_POST, v, None, env(cust["97526380"]["services"]["cards.list"]))
        print("Q:", v["select_q"])
        v.update(sel_kind="all"); run(MATCH_CODE, v); print("->", v["sel_result"], v["sel_tries"], v["select_q"])
        v.update(sel_kind="name", sel_name_said="premium kartım"); run(MATCH_CODE, v); print("->", v["sel_result"], v.get("sel_card"))
        v = {"now": "2026-10-12T10:30:00+03:00", "customerNumber": "93261864"}
